{
  "schema_version": 2,
  "name": "legroom-agent-traces-v1",
  "fixtures": [
    {
      "path": "fixtures/coding_agent_reads.json",
      "expected_terms": ["paginate.py", "total_pages", "page_size", "ValueError"],
      "checks": [
        {
          "name": "latest read call id",
          "path": [10, "tool_call_id"],
          "expected": "call_5"
        },
        {
          "name": "current turn exact",
          "path": [11, "content"],
          "expected": "Good, the fix is in place"
        }
      ]
    },
    {
      "path": "fixtures/grep_results.json",
      "expected_terms": ["CompressConfig", "proxy_server.py", "protect_recent"],
      "checks": [
        {
          "name": "search call id",
          "path": [2, "tool_call_id"],
          "expected": "call_1"
        }
      ]
    }
  ],
  "strategies": [
    {
      "name": "legroom_no_read_lifecycle",
      "base": "legroom",
      "config": {"read_lifecycle_enabled": false}
    },
    {
      "name": "legroom_no_cross_turn_dedup",
      "base": "legroom",
      "config": {"cross_turn_dedup_enabled": false}
    },
    {
      "name": "legroom_no_query_awareness",
      "base": "legroom",
      "config": {"query_aware": false}
    }
  ]
}
